import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { cartAPI } from './api'; // Your API functions are imported here
import CartItem from './CartItem';
import OrderSummary from './OrderSummary';
import './Cart.css'; // Your provided CSS file

const CartPage = () => {
    // --- State and API logic are now inside the component ---
    const [cart, setCart] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const navigate = useNavigate();

    // Helper function to calculate the total price from the items array
    const calculateTotal = (items = []) => {
        return items.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    };

    // Fetches the cart from the backend
    const fetchCart = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const response = await cartAPI.getCart();
            const cartData = response.data;
            cartData.items = cartData.items || [];
            cartData.total = calculateTotal(cartData.items);
            setCart(cartData);
        } catch (err) {
            setError('Could not fetch your cart. Please try again later.');
        } finally {
            setLoading(false);
        }
    }, []);

    // Optimistically updates item quantity
    const updateCartItem = async (productId, newQuantity) => {
        const originalCart = { ...cart };
        const updatedItems = originalCart.items.map(item =>
            item.productId === productId ? { ...item, quantity: newQuantity } : item
        );
        setCart({ ...originalCart, items: updatedItems, total: calculateTotal(updatedItems) });
        try {
            await cartAPI.updateCartItem(productId, newQuantity);
        } catch (err) {
            setError('Could not update item.');
            setCart(originalCart); // Revert on failure
        }
    };

    // Optimistically removes an item
    const removeFromCart = async (productId) => {
        const originalCart = { ...cart };
        const updatedItems = originalCart.items.filter(item => item.productId !== productId);
        setCart({ ...originalCart, items: updatedItems, total: calculateTotal(updatedItems) });
        try {
            await cartAPI.removeFromCart(productId);
        } catch (err) {
            setError('Could not remove item.');
            setCart(originalCart); // Revert on failure
        }
    };
    
    // NOTE: Your CSS doesn't have a class for the "Clear Cart" button.
    // I will add a div with a class "cart-header" around the title and button for alignment.
    // You can add styles for .cart-header and .clear-cart-btn to your CSS file if needed.
    const clearCart = async () => {
        const originalCart = { ...cart };
        setCart({ items: [], total: 0 });
        try {
            await cartAPI.clearCart();
        } catch (err) {
            setError('Could not clear cart.');
            setCart(originalCart); // Revert on failure
        }
    };

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (!token) {
            navigate('/login');
        } else {
            fetchCart();
        }
    }, [navigate, fetchCart]);

    const handleUpdateQuantity = (productId, newQuantity) => {
        if (newQuantity <= 0) {
            removeFromCart(productId);
        } else {
            updateCartItem(productId, newQuantity);
        }
    };

    if (loading) return <div className="cart-page-message">Loading your cart...</div>;
    if (error) return <div className="cart-page-message error">{error}</div>;

    if (!cart || !cart.items || cart.items.length === 0) {
        return (
            <div className="cart-page-empty">
                <h2>Your Shopping Cart is Empty</h2>
                <p>Start shopping to add items to your cart!</p>
                <button 
                    onClick={() => navigate('/')}
                    className="checkout-btn" // Re-using your green button style
                >
                    Continue Shopping
                </button>
            </div>
        );
    }

    return (
        <div className="cart-page">
            <main className="cart-items-container">
                <div className="cart-header"> {/* Added for layout */}
                    <h2>Shopping Cart</h2>
                    <button onClick={clearCart} className="clear-cart-btn">Clear Cart</button>
                </div>
                {cart.items.map(item => (
                    <CartItem 
                        key={item.productId}
                        item={item}
                        onUpdateQuantity={handleUpdateQuantity}
                        onRemoveItem={removeFromCart}
                    />
                ))}
            </main>
            <OrderSummary cart={cart} />
        </div>
    );
};

export default CartPage;
